@Override
public String getDescription() {
    return "User Account";
}

@Override
public User onCreate(User resource) {
    UserProfileProvider provider = session.getProvider(UserProfileProvider.class);
    RealmModel realm = session.getContext().getRealm();
    String username = realm.isRegistrationEmailAsUsername() ? resource.getEmail() : resource.getUserName();

    if (username == null) {
        throw new ModelValidationException(realm.isRegistrationEmailAsUsername() ? "email is required" : "username is required");
    }

    UserProfile profile = provider.create(UserProfileContext.SCIM, Map.of(UserModel.USERNAME, username));
    UserModel model = profile.create(false);
    UserModelAttributeRecorder recorder = new UserModelAttributeRecorder(model, new HashMap<>());

    populate(recorder, resource);
    persist(recorder);

    return createResourceTypeInstance(model, null, null);
}

@Override
public User update(User resource) {
    UserModel model = getModel(resource.getId());

    if (model == null || !hasPermission(model, getRealmResourceType(), AdminPermissionsSchema.MANAGE)) {
        throw new ForbiddenException();
    }

    UserModelAttributeRecorder recorder = createUserModelAttributeRecorder(model);

    populate(recorder, resource);
    persist(recorder);

    return onUpdate(model, resource);
}

@Override
public void patch(User existing, List<PatchOperation> operations) {
    Objects.requireNonNull(existing, "existing cannot be null");
    Objects.requireNonNull(operations, "operations cannot be null");

    if (operations.size() > MAX_PATCH_OPERATIONS) {
        throw new ScimPatchException(
                "PATCH request exceeds maximum allowed number of %d operations".formatted(MAX_PATCH_OPERATIONS));
    }

    UserModel model = getModel(existing.getId());

    if (model == null || !hasPermission(model, getRealmResourceType(), AdminPermissionsSchema.MANAGE)) {
        throw new ForbiddenException();
    }

    UserModelAttributeRecorder recorder = createUserModelAttributeRecorder(model);

    applyPatch(existing, recorder, operations);

    String stagedUsername = recorder.getUsername();

    if (isBlank(stagedUsername) && isUsernameReadOnly(recorder)) {
        throw new ModelValidationException("userName is required");
    }

    persist(recorder);
    onUpdate(model, existing);
}

private UserModelAttributeRecorder createUserModelAttributeRecorder(UserModel model) {
    return new UserModelAttributeRecorder(model, new HashMap<>(model.getAttributes()));
}

private boolean isUsernameReadOnly(UserModelAttributeRecorder recorder) {
    UserProfileProvider provider = session.getProvider(UserProfileProvider.class);
    UserProfile profile = provider.create(UserProfileContext.SCIM, recorder.getAttributes(), recorder.getDelegate());
    return profile.getAttributes().isReadOnly(UserModel.USERNAME);
}

private void persist(UserModelAttributeRecorder recorder) {
    UserProfileProvider provider = session.getProvider(UserProfileProvider.class);
    UserProfile profile = provider.create(UserProfileContext.SCIM, recorder.getAttributes(), recorder.getDelegate());

    try {
        profile.validate();
        profile.update(true);
    } catch (ValidationException ve) {
        throw handleValidationException(ve);
    }
}

@Override
protected User onUpdate(UserModel model, User resource) {
    model.setLastModifiedTimestamp(Time.currentTimeMillis());
    return createResourceTypeInstance(model, null, null);
}

@Override
public DefaultUserProfile(UserProfileMetadata metadata, Attributes attributes, Function<Attributes, UserModel> userCreator, UserModel user,
        KeycloakSession session) {
    this.metadata = metadata;
    this.userSupplier = userCreator;
    this.attributes = attributes;
    this.user = user;
    this.session = session;
}

@Override
public void validate() {
    ValidationException.ValidationExceptionBuilder validationExceptionBuilder = new ValidationException.ValidationExceptionBuilder();

    for (String attributeName : attributes.nameSet()) {
        this.attributes.validate(attributeName, validationExceptionBuilder);
    }

    if (validationExceptionBuilder.hasError()) {
        throw validationExceptionBuilder.build();
    }

    validated = true;
}

@Override
public UserModel create() throws ValidationException {
    return create(true);
}

@Override
public UserModel create(boolean validate) throws ValidationException {
    if (user != null) {
        throw new RuntimeException("User already created");
    }

    if (validate && !validated) {
        validate();
    }

    user = userSupplier.apply(this.attributes);

    return updateInternal(user, false);
}

@Override
public void update(boolean removeAttributes, AttributeChangeListener... changeListener) {
    if (!validated) {
        validate();
    }

    updateInternal(user, removeAttributes, changeListener);
}

private UserModel updateInternal(UserModel user, boolean removeAttributes, AttributeChangeListener... changeListener) {
    if (user == null) {
        throw new RuntimeException("No user model provided for persisting changes");
        throw new RuntimeException("No metadata is bound to the " + context + " context");
    }

    UserProfileMetadata metadata = configureUserProfile(defaultMetadata, session);
    Attributes profileAttributes = createAttributes(context, attributes, user, metadata);
    return new DefaultUserProfile(metadata, profileAttributes, createUserFactory(), user, session);
}

/**
 * Creates a {@link Function} for creating new users when the creating them using {@link UserProfile#create()}.
 *
 * @return a function for creating new users.
 */
private Function<Attributes, UserModel> createUserFactory() {
    return new Function<>() {
        private UserModel user;

        @Override
        public UserModel apply(Attributes attributes) {
            if (user == null) {
                String userName = attributes.getFirst(UserModel.USERNAME);

                // fallback to email in case email is allowed
                if (userName == null) {
                    userName = attributes.getFirst(UserModel.EMAIL);
                }

                user = session.users().addUser(session.getContext().getRealm(), userName);
            }

            return user;
        }
    };
}

